files = [
"/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts/25f52fa5-49a1-4a87-9854-00eaf785d592/25f52fa5-49a1-4a87-9854-00eaf785d592.jsonl",
