]
for fp in files:
    print("\n========", Path(fp).parent.name, "========")
    n=0
    with open(fp) as f:
        for i,line in enumerate(f):
            try:
                o=json.loads(line)
            except Exception:
                continue
            role=o.get("role") or o.get("type") or ""
            # various transcript shapes
            text=""
            if isinstance(o.get("message"), dict):
                c=o["message"].get("content")
                role=o["message"].get("role") or role
                if isinstance(c, str):
                    text=c
                elif isinstance(c, list):
                    parts=[]
                    for x in c:
                        if isinstance(x, dict) and x.get("type") in ("text","input_text") and x.get("text"):
                            parts.append(x["text"])
                        elif isinstance(x, str):
                            parts.append(x)
                    text="\n".join(parts)
            elif isinstance(o.get("content"), str):
                text=o["content"]
            if role in ("user","human") or "user_query" in text[:500]:
                # extract user_query if wrapped
                snippet=text
                if "<user_query>" in text:
                    snippet=text.split("<user_query>",1)[1].split("</user_query>",1)[0]
                snippet=snippet.strip().replace("\n"," ")[:400]
                if not snippet:
                    continue
                # skip huge system
                if snippet.startswith("【定时") or "AGENT_LOOP" in snippet[:80]:
                    print(f"L{i} SYS/WAKE {snippet[:180]}")
                else:
                    print(f"L{i} USER {snippet[:350]}")
                n+=1
    print("user-like", n)
